function OverManegeLoungeCardDetailsNode:FreshUI(cardInfo, isDetail, isInit, loungeIndex)
    self._cardInfo = cardInfo
    self._loungeIndex = loungeIndex
    local isShow = cardInfo ~= nil
        
    local status, oldStatus = self:InitStatus(isShow, isDetail)
    if status ~= oldStatus then
        self._status = status
        self:FreshUIAni(Status2AniName[status])  
    end

    if not isShow then
        return
    end
    
    if isDetail then
        self:FreshDetailUI(cardInfo)
    else
        self:FreshSimpleUI(cardInfo)
    end

    self:FreshTime(cardInfo.recoveryTime - os.time(), isDetail)
end

function OverManegeLoungeCardDetailsNode:InitStatus(isShow, isDetail)
    local oldStatus = self._status
    local status

    if isShow then
        if oldStatus == Status.SimpleInto or oldStatus == Status.DetailToSimple then
            status = isDetail and Status.SimpleToDetail or oldStatus
        elseif oldStatus == Status.DetailInto or oldStatus == Status.SimpleToDetail then
            status = isDetail and oldStatus or Status.DetailToSimple
        else
            status = isDetail and Status.DetailInto or Status.SimpleInto
        end
        
    else
        if oldStatus == Status.SimpleInto or oldStatus == Status.DetailToSimple then
            status = Status.SimpleOut
        elseif oldStatus == Status.DetailInto or oldStatus == Status.SimpleToDetail then
            status = Status.DetailOut
        else
            status = Status.None
        end
        
    end
 
    return status, oldStatus   
end

---FreshFeedEffectShowState
---刷新喂食效果 显示状态
function OverManegeLoungeCardDetailsNode:FreshFeedEffectShowState(isShow)
    if self._particleSystems == nil then
        self._particleSystems = self.UIFX_Finish.gameObject:GetComponentsInChildren(typeof(CS.UnityEngine.ParticleSystem))
    end
    if isShow then
        if KTool.IsActive(self.UIFX_Finish) then
            local particleSystems = self._particleSystems
            for i = 0, particleSystems.Length - 1 do
                ---@type UnityEngine.ParticleSystem
                local ps = particleSystems[i]
                ps:Play(true)
            end
        else
            KTool.SetActive(self.UIFX_Finish.gameObject, true)
        end
    end
end

