function OverManegeLoungeCardDetailsNode:FreshDetailUI(cardInfo)
    
    ---@type CardDojo
    local cardDojo = cardInfo.cardDojo
    local cardId   = cardDojo.cardId
    ---刷新职业
    self:FreshJob(cardId)

    ---@type CardVo
    local cardVo = cardConfMgr:GetCardByRefId(cardId)
    ---刷新卡牌信息
    self:FreshCardInfo(cardVo)

    ---刷新卡牌心情
    self:FreshMood(cardDojo.cafeEnergy, cardInfo.maxEnergy, true)
    
    UICommonUtils.FillCardHeadNode(self.CommonSmallHeadNode, 1, nil, cardDojo, true)
    
end

function OverManegeLoungeCardDetailsNode:FreshJob(cardId)
    ---@type MaidCoffeeCardInfoVo
    local vo = MaidCoffeeUtils.GetCardManagerInfoVo(cardId)
    if vo then
        local job = vo.job
        self.ImgBuff.Status = job
    end
end

function OverManegeLoungeCardDetailsNode:FreshCardInfo(cardVo)
    
    self.TextName1.text = cardVo.name
    self.TextName2.text = cardVo.descr
end

function OverManegeLoungeCardDetailsNode:FreshMood(cafeEnergy, maxEnergy, isDetail, loungeIndex)
    local status = MaidCoffeeUtils.GetCardMoodStatus(checkNumber(cafeEnergy))
    local ImgAttribute = isDetail and self.ImgAttribute or self.ImgAttributeSimpleDisplay
    ImgAttribute.Status = status

    local TextNumber = isDetail and self.TextNumber or self.TextNumberSimpleDisplay
    local color = MaidCoffeeConstants.CardMoodStatusColor[status] or MaidCoffeeConstants.CardMoodStatusColor[1]
    TextNumber.text = string.format("<color=%s>%s</color>/%s", color, cafeEnergy, maxEnergy)
end


function OverManegeLoungeCardDetailsNode:FreshDetailTimeShowState(isShow)
    if self._isShowDetailTime == isShow then return end
    
    self._isShowDetailTime = isShow
    GameUtils.UpdateUIShowState(self.Time.gameObject, self._isShowDetailTime)
    
end

function OverManegeLoungeCardDetailsNode:FreshTime(seconds, isDetail)
    local isShow = seconds > 0
    if isDetail then
        self:FreshDetailTimeShowState(isShow)
    else
        self:FreshSimpleTimeShowState(isShow)
    end
    if isShow then
        local TextNumberTime = isDetail and self.TextNumberTime or self.TextTimeSimpleDisplay
        TextNumberTime.text = GetTimeHMS9(seconds)
        
    end
end

