--region handler

function OverManegeLoungeCardDetailsNode:OnClickBtnFinishAction()
    local DataProvider = import("Game.MaidCoffee.MaidCoffeeUIDialog.Lounge.OverManegeLoungeDataProvider")
    local dataProvider = DataProvider:GetInstance()
    local loungeIndex  = self._loungeIndex
    local loungeData   = dataProvider:GetLoungeDataByIndex(loungeIndex)
    local playerCardId = self._cardInfo.cardDojo.id
    local cardIds     = {}
    local tInsert = table.insert
    for i, v in ipairs(loungeData.playerCardIds) do
        if v == 0 or v == playerCardId then
            tInsert(cardIds, 0)
        else
            tInsert(cardIds, v)
        end
    end
    -- local changeIds = {playerCardId}
    dataProvider:RequestLoungeUpdate(loungeData.roomId, cardIds, false)
end

--region handler

return OverManegeLoungeCardDetailsNode